<div class="reference-form mb-3">
    <h6>Reference @(Index + 1)</h6>

    <div class="row mb-2">
        <div class="col-md-6">
            <label class="form-label">Name *</label>
            <input type="text" class="form-control" value="@Entry.Name"
                   @onchange="e => Update(Entry with { Name = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Relationship *</label>
            <input type="text" class="form-control" value="@Entry.Relationship"
                   @onchange="e => Update(Entry with { Relationship = (string?)e.Value ?? string.Empty })" />
        </div>
    </div>

    <div class="row mb-2">
        <div class="col-md-6">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" value="@Entry.Email"
                   @onchange="e => Update(Entry with { Email = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="col-md-6">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" value="@Entry.Phone"
                   @onchange="e => Update(Entry with { Phone = (string?)e.Value ?? string.Empty })" />
        </div>
    </div>

    @if (ShowRemove)
    {
        <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
    }
    <hr />
</div>

@code {
    [Parameter, EditorRequired] public Reference Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback<Reference> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private async Task Update(Reference updated)
    {
        await OnEntryChanged.InvokeAsync(updated);
    }
}

@namespace sv_86aa30f482d948bc9857d2db46d3fd85.Components.Pages.Apply
@using sv_86aa30f482d948bc9857d2db46d3fd85.Models

<div class="personal-info-step">
    <h4>Personal Information</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="mb-3">
        <label class="form-label">Full Name *</label>
        <input type="text" class="form-control" value="@Model.FullName"
               @onchange="e => Model = Model with { FullName = (string?)e.Value ?? string.Empty }" />
    </div>

    <div class="mb-3">
        <label class="form-label">Email *</label>
        <input type="email" class="form-control" value="@Model.Email"
               @onchange="e => Model = Model with { Email = (string?)e.Value ?? string.Empty }" />
    </div>

    <div class="mb-3">
        <label class="form-label">Phone *</label>
        <input type="tel" class="form-control" value="@Model.Phone"
               @onchange="e => Model = Model with { Phone = (string?)e.Value ?? string.Empty }" />
    </div>

    <div class="mb-3">
        <label class="form-label">Address *</label>
        <textarea class="form-control" rows="2" value="@Model.Address"
                  @onchange="e => Model = Model with { Address = (string?)e.Value ?? string.Empty }"></textarea>
    </div>

    <div class="d-flex justify-content-end">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Next
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfo Model { get; set; } = new("", "", "", "");
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!emailValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }

            await OnNext.InvokeAsync(Model);
        }
        finally
        {
            IsValidating = false;
        }
    }
}

@namespace sv_86aa30f482d948bc9857d2db46d3fd85.Components.Pages.Apply
@using sv_86aa30f482d948bc9857d2db46d3fd85.Models

<div class="work-history-step">
    <h4>Work History</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="@Entries[index]"
                       Index="index"
                       ShowRemove="@(Entries.Count > 1)"
                       OnEntryChanged="e => UpdateEntry(index, e)"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Another Position
    </button>

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntry> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<WorkEntry>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateEntry(int index, WorkEntry updated)
    {
        Entries[index] = updated;
    }

    private void AddEntry()
    {
        Entries.Add(new WorkEntry("", "", DateTime.Today, null, ""));
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position requires at least a company name and job title.";
                return;
            }
        }

        await OnNext.InvokeAsync(Entries);
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

@namespace sv_86aa30f482d948bc9857d2db46d3fd85.Components.Pages.Apply
@using sv_86aa30f482d948bc9857d2db46d3fd85.Models

<div class="references-step">
    <h4>References</h4>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Entry="@References[index]"
                       Index="index"
                       ShowRemove="@(References.Count > 2)"
                       OnEntryChanged="e => UpdateReference(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
            + Add Reference
        </button>
    }

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public EventCallback<List<Reference>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateReference(int index, Reference updated)
    {
        References[index] = updated;
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new Reference("", "", "", ""));
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (References.Count < 2)
        {
            ErrorMessage = "At least 2 references are required.";
            return;
        }

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }
}

