{"file_text": "@namespace sv_86aa30f482d948bc9857d2db46d3fd85.Components.Pages.Apply
@using sv_86aa30f482d948bc9857d2db46d3fd85.Models

<div class="review-step">
    <h4>Review & Submit</h4>

    @if (IsSubmitted)
    {
        <div class="alert alert-success">
            <h5>Application Submitted Successfully!</h5>
            <p>Your application ID is: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(0)">Edit</button>
            </div>
            <div class="card-body">
                <p><strong>Name:</strong> @Personal.FullName</p>
                <p><strong>Email:</strong> @Personal.Email</p>
                <p><strong>Phone:</strong> @Personal.Phone</p>
                <p><strong>Address:</strong> @Personal.Address</p>
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(1)">Edit</button>
            </div>
            <div class="card-body">
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-2">
                        <strong>@entry.Title</strong> at @entry.Company<br />
                        <small class="text-muted">
                            @entry.StartDate.ToString("MMM yyyy") &ndash;
                            @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(2)">Edit</button>
            </div>
            <div class="card-body">
                @foreach (var r in References)
                {
                    <div class="mb-2">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <small>@r.Email &bull; @r.Phone</small>
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Cover Letter</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEdit.InvokeAsync(3)">Edit</button>
            </div>
            <div class="card-body">
                <p style="white-space: pre-wrap;">@CoverLetter</p>
            </div>
        </div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="HandleBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Application
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo Personal { get; set; } = default!;
    [Parameter] public List<WorkEntry> WorkEntries { get; set; } = new();
    [Parameter] public List<Reference> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public IApplicationService ApplicationService { get; set; } = default!;
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private bool IsSubmitting;
    private bool IsSubmitted;
    private int ApplicationId;
    private string? ErrorMessage;

    private async Task HandleBack()
    {
        await OnBack.InvokeAsync();
    }

    private async Task HandleSubmit()
    {
        IsSubmitting = true;
        ErrorMessage = null;

        try
        {
            var application = new JobApplication(
                Personal,
                new WorkHistory(WorkEntries),
                References,
                CoverLetter);

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsSubmitting = false;
        }
    }
}
